class Solution {
    public int maxSubarraySumCircular(int[] nums) {
        int total = nums[0];
        int maximumEnding = nums[0];
        int maximumSubarray = nums[0];
        int minimumEnding = nums[0];
        int minimumSubarray = nums[0];

        for (int index = 1; index < nums.length; index++) {
            int value = nums[index];
            total += value;
            maximumEnding = Math.max(value, maximumEnding + value);
            maximumSubarray = Math.max(maximumSubarray, maximumEnding);
            minimumEnding = Math.min(value, minimumEnding + value);
            minimumSubarray = Math.min(minimumSubarray, minimumEnding);
        }

        if (maximumSubarray < 0) {
            return maximumSubarray;
        }
        return Math.max(maximumSubarray, total - minimumSubarray);
    }
}
